import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.4Y_9FogC.js";const i="/assets/TheengsGateway_controllers.DaGqatR6.png",d=JSON.parse('{"title":"MQTT integration (option)","description":"","frontmatter":{},"headers":[],"relativePath":"prerequisites/controller.md","filePath":"prerequisites/controller.md","lastUpdated":1780765817000}'),l={name:"prerequisites/controller.md"};function n(s,e,h,p,c,m){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="mqtt-integration-option" tabindex="-1">MQTT integration (option) <a class="header-anchor" href="#mqtt-integration-option" aria-label="Permalink to &quot;MQTT integration (option)&quot;">​</a></h1><h2 id="broker" tabindex="-1">Broker <a class="header-anchor" href="#broker" aria-label="Permalink to &quot;Broker&quot;">​</a></h2><p>The broker will act as an intermediary between Theengs App and your <a href="/prerequisites/controller.html">controller</a>, it can be seen as a centralized hub at the heart of your automation system. It carry on messages following a publish / subscribe mechanism.</p><p>All the events or commands could pass by the broker.</p><p>There are many choices of brokers, here are some of the most popular:</p><ul><li><a href="https://mosquitto.org/" target="_blank" rel="noreferrer">Mosquitto</a> (Open source)</li><li><a href="https://moquette-io.github.io/moquette/" target="_blank" rel="noreferrer">Moquette</a> (Open source)</li><li><a href="https://www.hivemq.com/hivemq/features/" target="_blank" rel="noreferrer">HiveMQ</a></li><li>Embedded MQTT brokers (Home Assistant and OpenHAB)</li></ul><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Theengs App can connect to MQTT brokers either in plaintext (default port <code>1883</code>) or over TLS (typically port <code>8883</code>), including HiveMQ Cloud and other public-CA brokers as well as private brokers with self-signed certificates. See the <a href="/use/use.html#mqtt-integration">MQTT integration section</a> for the TLS setup.</p></div><p>This <a href="https://en.wikipedia.org/wiki/Comparison_of_MQTT_implementations" target="_blank" rel="noreferrer">wikipedia list</a> gives you more details about the different choices you have. This <a href="https://github.com/mqtt/mqtt.github.io/wiki/libraries" target="_blank" rel="noreferrer">github list</a> seems to be the most exhaustive ones. Here is also some <a href="https://www.hivemq.com/blog/top-10-mqtt-broker-criteria/" target="_blank" rel="noreferrer">ideas of criteria</a> from HiveMQ.</p><p>Once your broker is installed it can be interesting to see the traffic passing to it and to publish data, so as to do that there are several tools available:</p><ul><li><a href="http://mqtt-explorer.com/" target="_blank" rel="noreferrer">MQTT Explorer</a></li><li><a href="https://github.com/hivemq/hivemq-mqtt-web-client" target="_blank" rel="noreferrer">HIVE MQ Web client</a></li><li><a href="https://mqttfx.jensd.de/" target="_blank" rel="noreferrer">MQTT FX</a></li></ul><p>MQTT enables you to connect easily a controller so as to monitor, control and automate scenariOS.</p><h2 id="controller" tabindex="-1">Controller <a class="header-anchor" href="#controller" aria-label="Permalink to &quot;Controller&quot;">​</a></h2><p>The following controllers (and many other software) are compatible with MQTT:</p><p><img src="'+i+'" alt="controllers"></p><p>TheengsApp is independent from these projects, you have the liberty of choice among all the compatible software.</p><ul><li><a href="https://www.openhab.org" target="_blank" rel="noreferrer">OpenHAB</a></li><li><a href="https://www.home-assistant.io" target="_blank" rel="noreferrer">Home Assistant</a></li><li><a href="https://www.domoticz.com" target="_blank" rel="noreferrer">Domoticz</a></li><li><a href="https://www.jeedom.com" target="_blank" rel="noreferrer">Jeedom</a></li><li><a href="https://nodered.org" target="_blank" rel="noreferrer">Node Red</a></li><li><a href="https://fhem.de" target="_blank" rel="noreferrer">FHEM</a></li><li><a href="https://www.iobroker.net/" target="_blank" rel="noreferrer">IO Broker</a></li></ul>',16)])])}const b=t(l,[["render",n]]);export{d as __pageData,b as default};
